import{c as t,Q as e,j as s,m as i}from"./chunks/framework.DOi4mjdC.js";const h=JSON.parse('{"title":"GetCumSumMaxMinTmpSize","description":"","frontmatter":{},"headers":[{"level":1,"title":"GetCumSumMaxMinTmpSize","slug":"getcumsummaxmintmpsize"},{"level":2,"title":"功能说明","slug":"功能说明"},{"level":2,"title":"函数原型","slug":"函数原型"},{"level":2,"title":"参数说明","slug":"参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明"},{"level":2,"title":"调用示例","slug":"调用示例"}],"relativePath":"api/SIMD-API/高阶API/数学计算/CumSum接口/GetCumSumMaxMinTmpSize.md","filePath":"api/SIMD-API/高阶API/数学计算/CumSum接口/GetCumSumMaxMinTmpSize.md"}'),n={name:"api/SIMD-API/高阶API/数学计算/CumSum接口/GetCumSumMaxMinTmpSize.md"};function l(u,a,p,m,r,d){return e(),s("div",null,[...a[0]||(a[0]=[i(`<h1 id="getcumsummaxmintmpsize" tabindex="-1">GetCumSumMaxMinTmpSize <a class="header-anchor" href="#getcumsummaxmintmpsize" aria-label="Permalink to &quot;GetCumSumMaxMinTmpSize&quot;">​</a></h1><h2 id="功能说明" tabindex="-1">功能说明 <a class="header-anchor" href="#功能说明" aria-label="Permalink to &quot;功能说明&quot;">​</a></h2><p>kernel侧CumSum接口的计算需要开发者预留/申请临时空间，本接口用于在host侧获取预留/申请的最大和最小临时空间大小，开发者基于此范围选择合适的空间大小作为Tiling参数传递到kernel侧使用。</p><ul><li>为保证功能正确，预留/申请的临时空间大小不能小于最小临时空间大小。</li><li>在最小临时空间-最大临时空间范围内，随着临时空间增大，kernel侧接口计算性能会有一定程度的优化提升。为了达到更好的性能，开发者可以根据实际的内存使用情况进行空间预留/申请。</li></ul><h2 id="函数原型" tabindex="-1">函数原型 <a class="header-anchor" href="#函数原型" aria-label="Permalink to &quot;函数原型&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>void GetCumSumMaxMinTmpSize(const ge::Shape&amp; srcShape, const uint32_t typeSize, const bool isLastAxis, const bool isReuseSource, uint32_t&amp; maxValue, uint32_t&amp; minValue)</span></span></code></pre></div><h2 id="参数说明" tabindex="-1">参数说明 <a class="header-anchor" href="#参数说明" aria-label="Permalink to &quot;参数说明&quot;">​</a></h2><p><strong>表 1</strong> 参数说明</p><table tabindex="0"><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>srcShape</td><td>输入</td><td>输入的shape信息。</td></tr><tr><td>typeSize</td><td>输入</td><td>输入的数据类型大小，单位为字节。比如输入的数据类型为half，此处应传入2。</td></tr><tr><td>isReuseSource</td><td>输入</td><td>是否复用源操作数输入的空间。</td></tr><tr><td>isLastAxis</td><td>输入</td><td>定义是first轴处理还是last轴处理。</td></tr><tr><td>maxValue</td><td>输出</td><td>Cumsum接口能完成计算所需的最大临时空间大小，超出该值的空间不会被该接口使用。 请注意，maxValue仅作为参考值，有可能大于Unified Buffer剩余空间的大小，该场景下，开发者需要根据Unified Buffer剩余空间的大小来选取合适的临时空间大小。</td></tr><tr><td>minValue</td><td>输出</td><td>Cumsum接口能完成计算所需最小临时空间大小。为保证功能正确，接口计算时预留/申请的临时空间不能小于该数值。</td></tr></tbody></table><h2 id="返回值说明" tabindex="-1">返回值说明 <a class="header-anchor" href="#返回值说明" aria-label="Permalink to &quot;返回值说明&quot;">​</a></h2><p>无</p><h2 id="约束说明" tabindex="-1">约束说明 <a class="header-anchor" href="#约束说明" aria-label="Permalink to &quot;约束说明&quot;">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="./../../../通用说明和约束.html#section796754519912">通用地址对齐约束</a>。</li><li>输入input只支持二维结构。</li></ul><h2 id="调用示例" tabindex="-1">调用示例 <a class="header-anchor" href="#调用示例" aria-label="Permalink to &quot;调用示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// 输入shape为32*32的矩阵；算子输入的数据类型为half；isLastAxis传入默认值true，isReuseSource传入默认值false</span></span>
<span class="line"><span>uint32_t firstDim = 32;</span></span>
<span class="line"><span>uint32_t lastDim = 32;</span></span>
<span class="line"><span>std::vector&lt;int64_t&gt; srcShapeDims = {firstDim, lastDim};</span></span>
<span class="line"><span>auto srcShape = ge::Shape(srcShapeDims);</span></span>
<span class="line"><span>uint32_t maxValue = 0;</span></span>
<span class="line"><span>uint32_t minValue = 0;</span></span>
<span class="line"><span>AscendC::GetCumSumMaxMinTmpSize(srcShape, 2, true, false, maxValue, minValue);</span></span></code></pre></div>`,15)])])}const c=t(n,[["render",l]]);export{h as __pageData,c as default};
